parameters.jsCode:
// Self-contained Australian Medicare & Provider Number Checksum Gate
const rawText = String($input.item.json.content?.[0]?.text || '{}').slice(0, 16384).replace(/```json|```/g, '').trim();
let data;
try {
  data = JSON.parse(rawText);
} catch (err) {
  return {
    json: {
      status: 'quarantined_dlq',
      quarantined_at: new Date().toISOString(),
      patient_initials: '?.?.',
      violations: [{ field: '__root__', message: 'Invalid JSON from model' }]
    }
  };
}

if (!data || typeof data !== 'object' || Array.isArray(data)) {
  return {
    json: {
      status: 'quarantined_dlq',
      quarantined_at: new Date().toISOString(),
      patient_initials: '?.?.',
      violations: [{ field: '__root__', message: 'Model output must be a JSON object' }]
    }
  };
}

function cleanText(val, maxLen = 200) {
  return String(val || '')
    .replace(/[\u0000-\u001F\u007F`]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, maxLen);
}

function escapeSlackMrkdwn(val, maxLen = 200) {
  return cleanText(val, maxLen)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const violations = [];

function isValidIsoDate(str, { allowFuture = false } = {}) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(str || ''))) return false;
  const [y, m, d] = str.split('-').map(Number);
  if (y < 1900 || y > 2100) return false;
  const dt = new Date(Date.UTC(y, m - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return false;
  if (!allowFuture && dt.getTime() > Date.now() + 86400000) return false;
  return true;
}

function validateMedicare(raw) {
  const digits = String(raw || '').replace(/[\s-]/g, '');
  if (!/^\d{11}$/.test(digits)) return { ok: false, msg: 'Medicare number must be 11 digits (10-digit card number + 1-digit IRN)' };
  if (!'23456'.includes(digits[0])) return { ok: false, msg: 'Medicare first digit must be 2..6' };
  const weights = [1, 3, 7, 9, 1, 3, 7, 9];
  const sum = weights.reduce((acc, w, i) => acc + Number(digits[i]) * w, 0);
  if (sum % 10 !== Number(digits[8])) {
    return { ok: false, msg: 'Medicare checksum failed' };
  }
  if (digits[9] === '0') return { ok: false, msg: 'Medicare issue number (10th digit) cannot be 0' };
  if (digits[10] === '0') return { ok: false, msg: 'Medicare IRN (11th digit) cannot be 0' };
  return {
    ok: true,
    normalised: `${digits.slice(0, 4)}-${digits.slice(4, 9)}-${digits[9]}`,
    irn: digits[10]
  };
}

function validateProvider(raw) {
  let cleaned = String(raw || '').replace(/[\s-]/g, '').toUpperCase();
  if (cleaned.length === 7) cleaned = '0' + cleaned;
  if (!/^\d{6}[0-9A-Z]{2}$/.test(cleaned)) return { ok: false, msg: 'Provider number must be 6 digits + PLV + check char' };
  const stemWeights = [3, 5, 8, 4, 2, 1];
  const plvChars = '0123456789ABCDEFGHJKLMNPQRTUVWXY';
  const checkChars = 'YXWTLKJHFBA';
  const plvIndex = plvChars.indexOf(cleaned[6]);
  if (plvIndex === -1) return { ok: false, msg: 'Invalid Practice Location character' };
  const stemSum = stemWeights.reduce((acc, w, i) => acc + Number(cleaned[i]) * w, 0);
  const expected = checkChars[(stemSum + plvIndex * 6) % 11];
  if (cleaned[7] !== expected) {
    return { ok: false, msg: 'Provider PLV mod-11 checksum failed' };
  }
  return { ok: true, normalised: cleaned };
}

const firstName = cleanText(data.first_name, 80);
const lastName = cleanText(data.last_name, 80);
if (firstName.length < 1) {
  violations.push({ field: 'first_name', message: 'Missing patient first_name' });
}
if (lastName.length < 1) {
  violations.push({ field: 'last_name', message: 'Missing patient last_name' });
}
if (!isValidIsoDate(data.date_of_birth, { allowFuture: false })) {
  violations.push({ field: 'date_of_birth', message: 'Invalid calendar date_of_birth (expected past YYYY-MM-DD)' });
}
if (!isValidIsoDate(data.referral_date, { allowFuture: false })) {
  violations.push({ field: 'referral_date', message: 'Invalid calendar referral_date (expected YYYY-MM-DD)' });
}

const ALLOWED_URGENCY = ['urgent', 'priority', 'routine'];
const urgencyTier = String(data.urgency_tier || 'routine').trim().toLowerCase();
if (!ALLOWED_URGENCY.includes(urgencyTier)) {
  violations.push({ field: 'urgency_tier', message: 'urgency_tier must be urgent, priority, or routine' });
}

const med = validateMedicare(data.medicare_number);
if (!med.ok) violations.push({ field: 'medicare_number', message: med.msg });

const prov = validateProvider(data.referring_provider_no);
if (!prov.ok) violations.push({ field: 'referring_provider_no', message: prov.msg });

const firstInitial = (firstName.match(/[A-Za-z0-9]/) || ['?'])[0].toUpperCase();
const lastInitial = (lastName.match(/[A-Za-z0-9]/) || ['?'])[0].toUpperCase();
const patientInitials = escapeSlackMrkdwn(`${firstInitial}.${lastInitial}.`, 10);

if (violations.length > 0) {
  return {
    json: {
      status: 'quarantined_dlq',
      quarantined_at: new Date().toISOString(),
      patient_initials: patientInitials,
      violations
    }
  };
}

const cleanNotes = cleanText(data.notes, 500);
const cleanPhone = cleanText(data.phone, 24);

return {
  json: {
    status: 'committed',
    validated_at: new Date().toISOString(),
    cliniko_patient_payload: {
      first_name: firstName,
      last_name: lastName,
      date_of_birth: data.date_of_birth,
      medicare: med.normalised,
      medicare_reference_number: med.irn,
      referral_source: `Provider ${prov.normalised} (${data.referral_date})`,
      notes: `[${urgencyTier.toUpperCase()}] ${cleanNotes}`.trim(),
      patient_phone_numbers: cleanPhone
        ? [{ phone_type: 'Mobile', number: cleanPhone }]
        : []
    }
  }
};

